package frc.robot.Autos;

import org.wpilib.math.geometry.Pose2d;
import org.wpilib.math.geometry.Rotation2d;
import java.util.Map;
import java.util.OptionalInt;



/**
 * A class containing the name, start pose, end pose, and total time of every Choreo trajectory.
 * This prevents your code from referencing deleted or misspelled trajectories,
 * and removes the need for JSON parsing to load a trajectory's essential data.
 * DO NOT MODIFY THIS FILE YOURSELF! It is automatically generated by Choreo.
 */
public record ChoreoTraj(
    String name,
    OptionalInt segment,
    double totalTimeSecs,
    Pose2d initialPoseBlue,
    Pose2d endPoseBlue
) {
    public static final ChoreoTraj mid = new ChoreoTraj(
        "mid",
        OptionalInt.empty(),
        1.26722,
        new Pose2d(3.59804, 4.0499, Rotation2d.fromRadians(0)),
        new Pose2d(1.64842, 4.09484, Rotation2d.fromRadians(0))
    );
    public static final ChoreoTraj mid_left = new ChoreoTraj(
        "mid_left",
        OptionalInt.empty(),
        1.16755,
        new Pose2d(3.66123, 6.12339, Rotation2d.fromRadians(0)),
        new Pose2d(0.44278, 5.04066, Rotation2d.fromRadians(0))
    );
    public static final ChoreoTraj mid_right = new ChoreoTraj(
        "mid_right",
        OptionalInt.empty(),
        1.27199,
        new Pose2d(3.62396, 1.96342, Rotation2d.fromRadians(0)),
        new Pose2d(2.73534, 2.0856, Rotation2d.fromRadians(0.82619))
    );
    public static final ChoreoTraj mid_to_depo = new ChoreoTraj(
        "mid_to_depo",
        OptionalInt.empty(),
        6.45294,
        new Pose2d(3.59804, 4.0499, Rotation2d.fromRadians(0)),
        new Pose2d(2.73246, 5.80914, Rotation2d.fromRadians(-0.75361))
    );
    public static final ChoreoTraj mid_tuning = new ChoreoTraj(
        "mid_tuning",
        OptionalInt.empty(),
        4.34471,
        new Pose2d(3.59948, 4.02783, Rotation2d.fromRadians(0)),
        new Pose2d(3.5, 4.02783, Rotation2d.fromRadians(-1.55502))
    );
    public static final ChoreoTraj NewPath_copy1 = new ChoreoTraj(
        "NewPath_copy1",
        OptionalInt.empty(),
        7.03107,
        new Pose2d(4.40175, 7.1743, Rotation2d.fromRadians(3.13514)),
        new Pose2d(4.37566, 1.0303, Rotation2d.fromRadians(0))
    );
    public static final ChoreoTraj trench_left_left_mid_chill = new ChoreoTraj(
        "trench_left_left_mid_chill",
        OptionalInt.empty(),
        7.76138,
        new Pose2d(4.33531, 7.65401, Rotation2d.fromRadians(0)),
        new Pose2d(3.08058, 5.32781, Rotation2d.fromRadians(-0.68848))
    );
    public static final ChoreoTraj trench_right_left_through_evil = new ChoreoTraj(
        "trench_right_left_through_evil",
        OptionalInt.empty(),
        9.01847,
        new Pose2d(4.37425, 0.39097, Rotation2d.fromRadians(0)),
        new Pose2d(3.04692, 6.69648, Rotation2d.fromRadians(-1.03694))
    );
    public static final ChoreoTraj trench_right_right_mid_chill = new ChoreoTraj(
        "trench_right_right_mid_chill",
        OptionalInt.empty(),
        8.28211,
        new Pose2d(4.37425, 0.39097, Rotation2d.fromRadians(0)),
        new Pose2d(3.14332, 1.95606, Rotation2d.fromRadians(0.9573))
    );

    /**
     * A map between trajectory names and their corresponding data.
     * This allows for trajectory data to be looked up with strings during runtime.
     */
    public static final Map<String, ChoreoTraj> ALL_TRAJECTORIES = Map.ofEntries(
        Map.entry("mid", mid),
        Map.entry("mid_left", mid_left),
        Map.entry("mid_right", mid_right),
        Map.entry("mid_to_depo", mid_to_depo),
        Map.entry("mid_tuning", mid_tuning),
        Map.entry("NewPath_copy1", NewPath_copy1),
        Map.entry("trench_left_left_mid_chill", trench_left_left_mid_chill),
        Map.entry("trench_right_left_through_evil", trench_right_left_through_evil),
        Map.entry("trench_right_right_mid_chill", trench_right_right_mid_chill)
    );

    /**
     * Looks up the ChoreoTraj segment of the given overall ChoreoTraj.
     * WARNING: will raise an exception if not called with a valid segment index.
     */
    public ChoreoTraj segment(int segment) {
        var traj = ChoreoTraj.ALL_TRAJECTORIES.get(this.name + "$" + segment);
        if (traj == null) {
            throw new NullPointerException("Trajectory " + this.name + " does not have segment #" + segment + ".");
        }
        return traj;
    }
    
}
